create or replace TABLE KFL_PRODUCTION.DBP_DATA.ARTBEW_MO_SUM_2 cluster by (KJMO)(
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant_2 im DWH.',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup_2 ID wird verwendet für Beziehung Lager zu Verteilzentrum',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	KJMO NUMBER(38,0) NOT NULL COMMENT 'Kalenderjahresmonat.',
	GP_ID NUMBER(38,0) NOT NULL COMMENT 'Geschäftspartner-ID (auch Lieferanten-ID).',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Artikelnummer im DWH. Input: Artikel_2-ID einschließlich der Generationen-ID (9-stellig); Output: 7-stellige L&S-ID + Counter = 8-stellige Artikel_2-ID. WWNNNNPC (Warengruppe, Nummer, Prüfziffer, Counter) Regel: Neuer Artikel_2 -> Counter +1.',
	BEWART_ID NUMBER(38,0) NOT NULL COMMENT 'Bewegungsart ID. Bewegungsarten > 1000 beziehen sich auf Warenausgang, < 1000 auf Wareneingang.',
	POSTEN_ID VARCHAR(2) NOT NULL COMMENT 'Postenkennzeichen. Für Artikel_2, die nicht staendig im Sortiment sind. Angereichert jeweils aktuell aus dem historisierten Artikelstamm art_per.Wird für den Split der Wochenebene in Aggregat benötigt.',
	BEWART_DET_ID NUMBER(38,0) NOT NULL DEFAULT 9999 COMMENT 'Detaillierte Bewegungsart zum Aufbruch der bestehenden bewart_id.',
	EAN_KASSE NUMBER(26,0) NOT NULL DEFAULT 0 COMMENT 'Von den Kassensystemen gelieferte EAN_2 / GTIN.',
	WRG_ID VARCHAR(3) COLLATE 'en-ci' COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR.',
	UMRECHNUNGSKURS_HIST NUMBER(38,5) NOT NULL DEFAULT 0 COMMENT 'Historischer Berichtskurs aus dbp_data.kurs_2 ',
	MENGE NUMBER(38,4) COMMENT 'Menge der Artikelbewegung (kann in Stück oder bei Gewichtsartikeln in KG sein).',
	UMSATZ_NETTO NUMBER(38,4) COMMENT 'Umsatz vermindert um den Mehrwertsteuerbetrag.',
	DIFF_UMSATZ_NETTO_KONZ NUMBER(38,4) COMMENT 'Von der Konzernwährung abweichender Umsatz netto.',
	UMSATZ_MWST_BETRAG NUMBER(38,4) COMMENT 'Der Mehrwertsteuerbetrag wird hier redundant abgelegt. Er ist eigentlich pro Artikel_2 als Mehrwertsteuersatz im Artikelstamm ersichtlich muss aber hier aus Performancegründen auch stehen.',
	DIFF_UMSATZ_MWST_BETRAG_KONZ NUMBER(38,4) COMMENT 'Von der Konzernwährung abweichender Mehrwertsteuerbetrag.',
	EK_BRUTTO NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Einkaufspreis brutto (Bedeutung vgl. Kalkulationsschema).',
	DIFF_EK_BRUTTO_KONZ NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Von der Konzernwährung abweichender Einkaufspreis brutto.',
	EK_NETTO NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Einkaufspreis netto (Bedeutung vgl. Kalkulationsschema).',
	DIFF_EK_NETTO_KONZ NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Von der Konzernwährung abweichender Einkaufspreis netto.',
	EK_NETTONETTO NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Einkaufspreis nettonetto (Bedeutung vgl. Kalkulationsschema).',
	DIFF_EK_NETTONETTO_KONZ NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Von der Konzernwährung abweichender Einkaufspreis nettonetto.',
	EK_KAL_BASIS NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Kalkulationsbasis (Bedeutung vgl. Kalkulationsschema).',
	DIFF_EK_KAL_BASIS_KONZ NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Von der Konzernwährung abweichender Einkaufspreis Kalkulationsbasis.',
	EK_MEP NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Markteinstandspreis (Bedeutung vgl. Kalkulationsschema).',
	DIFF_EK_MEP_KONZ NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Von der Konzernwährung abweichender Einkaufspreis Markteinstandspreis.',
	EK_MEP_VOR_FWU NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Markteinstandspreis vor Festwertumlage: Mit Einführung der Festwertumlage in KMO braucht es einen \"alten\" EK3Netto ohne die Festwertumlage als Vergleichswert. Dieser Wert wird aus SAP über ZEKP.MEPOL geliefert.',
	EK_MEP_VOR_FWU_KONZ NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Markteinstandspreis vor Festwertumlage in Konzernwährung, wenn Landeswährung davon abweicht. Mit Einführung der Festwertumlage in KMO braucht es einen \"alten\" EK3Netto ohne die Festwertumlage als Vergleichswert. Dieser Wert wird aus SAP über ZEKP.MEPOL geliefert.',
	EINSTANDSPREIS NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Kaufland Einstandspreis (Bedeutung vgl. Kalkulationsschema).',
	DIFF_EINSTANDSPREIS_KONZ NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Von der Konzernwährung abweichender Einstandspreis.',
	LOGKOSTENZUSCHLAG NUMBER(38,4) COMMENT 'Logistikkostenzuschlag (ein kalkulierter Wert für die Zentrallagerkosten, der bei zentraler Lieferung Bestandteil einiger Einstandspreise ist).',
	DIFF_LOGKOSTENZUSCHLAG_KONZ NUMBER(38,4) COMMENT 'Von der Konzernwährung abweichender Logistikkostenzuschlag.',
	HERST_ID NUMBER(38,0) COMMENT 'Der Hersteller des Artikels (kann abweichend zum Lieferanten sein).',
	EK_NETTO_BNK NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Einkaufspreis netto plus Bezugsnebenkosten (Bedeutung vgl. Kalkulationsschema).',
	DIFF_EK_NETTO_BNK_KONZ NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Differenz des Einkaufspreis netto plus Bezugsnebenkosten zur Konzernwährung.',
	EK_NETTO_BNK_SACHK NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Einkaufspreis netto plus Bezugsnebenkosten plus Sachkosten (Bedeutung vgl. Kalkulationsschema).',
	DIFF_EK_NETTO_BNK_SACHK_KONZ NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Differenz des Einkaufspreis netto plus Bezugsnebenkosten plus Sachkosten zur Konzernwährung.',
	EK_GLD NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Gleitender Durchschnittspreis. In KMO die Basis zur Bewertung der Bestände. Hier aus mseg abgeleitet.',
	DIFF_EK_GLD_KONZ NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Differenz zum gleitenden Durchschnittspreis in Konzernwährung.',
	BONUSBASIS NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Die Bonusbasis bildet für Artikel_2 mit Luxussteuer die Preisbasis der Reduzierungen nach Abzug der Luxussteuer auf der Ebene EK1N. Quelle: ZEKP.ABONBA.',
	BONUSBASIS_KONZ NUMBER(38,4) WITH MASKING POLICY #unknown_policy COMMENT 'Bonusbasis in Konzernwährung, wenn Landeswährung davon abweicht. Die Bonusbasis bildet für Artikel_2 mit Luxussteuer die Preisbasis der Reduzierungen nach Abzug der Luxussteuer auf der Ebene EK1N. Quelle: ZEKP.ABONBA.',
	PV_AKTION NUMBER(38,4) NOT NULL DEFAULT 0 COMMENT 'PV-Kennzahlen werden auf Bondatenebene berechnet und im Anschluss daran aggregiert hier eingefügt. PV wenn Abverkauf durch eine_2 Aktion_2 zustande gekommen ist.',
	PV_AKTION_KONZ NUMBER(38,4) NOT NULL DEFAULT 0 COMMENT 'PV-Kennzahlen werden auf Bondatenebene berechnet und im Anschluss daran aggregiert hier eingefügt. PV wenn Abverkauf durch eine_2 Aktion_2 zustande gekommen ist.',
	PV_BBY NUMBER(38,4) NOT NULL DEFAULT 0 COMMENT 'PV-Kennzahlen werden auf Bondatenebene berechnet und im Anschluss daran aggregiert hier eingefügt. PV wenn Abverkauf durch eine_2 Standard BBY zustande gekommen ist.',
	PV_BBY_KONZ NUMBER(38,4) NOT NULL DEFAULT 0 COMMENT 'PV-Kennzahlen in Konzernwährung werden auf Bondatenebene berechnet und im Anschluss daran aggregiert hier eingefügt. PV wenn Abverkauf durch eine_2 Standard BBY zustande gekommen ist.',
	PV_KDN_BBY NUMBER(38,4) NOT NULL DEFAULT 0 COMMENT 'PV-Kennzahlen werden auf Bondatenebene berechnet und im Anschluss daran aggregiert hier eingefügt. PV wenn Abverkauf durch einen KDN Kundenkarten BBY zustande gekommen ist.',
	PV_KDN_BBY_KONZ NUMBER(38,4) NOT NULL DEFAULT 0 COMMENT 'PV-Kennzahlen in Konzernwährung werden auf Bondatenebene berechnet und im Anschluss daran aggregiert hier eingefügt. PV wenn Abverkauf durch einen KDN Kundenkarten BBY zustande gekommen ist.',
	PV_KDP_BBY NUMBER(38,4) NOT NULL DEFAULT 0 COMMENT 'PV-Kennzahlen werden auf Bondatenebene berechnet und im Anschluss daran aggregiert hier eingefügt. PV wenn Abverkauf durch einen KDP Kundenkarte BBY zustande gekommen ist.',
	PV_KDP_BBY_KONZ NUMBER(38,4) NOT NULL DEFAULT 0 COMMENT 'PV-Kennzahlen in Konzernwährung werden auf Bondatenebene berechnet und im Anschluss daran aggregiert hier eingefügt. PV wenn Abverkauf durch einen KDP Kundenkarte BBY zustande gekommen ist.',
	PV_AKTION_BBY NUMBER(38,4) NOT NULL DEFAULT 0 COMMENT 'PV-Kennzahlen werden auf Bondatenebene berechnet und im Anschluss daran aggregiert hier eingefügt. PV wenn Abverkauf durch eine_2 Aktion_2 in Kombination mit einem Standard BBY zustande gekommen ist. PV Differenz BBY-Preis zu Aktionspreis fließt in pv_bby. PV Differenz Aktionspreis zu Normalpreis fließt in pv_aktion_bby.',
	PV_AKTION_BBY_KONZ NUMBER(38,4) NOT NULL DEFAULT 0 COMMENT 'PV-Kennzahlen in Konzernwährung werden auf Bondatenebene berechnet und im Anschluss daran aggregiert hier eingefügt. PV wenn Abverkauf durch eine_2 Aktion_2 in Kombination mit einem Standard BBY zustande gekommen ist. PV Differenz BBY-Preis zu Aktionspreis fließt in pv_bby. PV Differenz Aktionspreis zu Normalpreis fließt in pv_aktion_bby.',
	PV_AKTION_KDN_BBY NUMBER(38,4) NOT NULL DEFAULT 0 COMMENT 'PV-Kennzahlen werden auf Bondatenebene berechnet und im Anschluss daran aggregiert hier eingefügt. PV wenn Abverkauf durch eine_2 Aktion_2 in Kombination mit einem Standard BBY zustande gekommen ist. PV Differenz BBY-Preis zu Aktionspreis fließt in pv_bby. PV Differenz Aktionspreis zu Normalpreis fließt in pv_aktion_bby.',
	PV_AKTION_KDN_BBY_KONZ NUMBER(38,4) NOT NULL DEFAULT 0 COMMENT 'PV-Kennzahlen in Konzernwährung werden auf Bondatenebene berechnet und im Anschluss daran aggregiert hier eingefügt. PV wenn Abverkauf durch eine_2 Aktion_2 in Kombination mit einem Standard BBY zustande gekommen ist. PV Differenz BBY-Preis zu Aktionspreis fließt in pv_bby. PV Differenz Aktionspreis zu Normalpreis fließt in pv_aktion_bby.',
	PV_AKTION_KDP_BBY NUMBER(38,4) NOT NULL DEFAULT 0 COMMENT 'PV-Kennzahlen werden auf Bondatenebene berechnet und im Anschluss daran aggregiert hier eingefügt. PV wenn Abverkauf durch eine_2 Aktion_2 in Kombination mit einem KD Kundenkarten BBY zustande gekommen ist. PV Differenz KDP-BBY-Preis zu Aktionspreis fließt in pv_kdp_bby. PV Differenz Aktionspreis zu Normalpreis fließt in pv_aktion_kdp_bby.',
	PV_AKTION_KDP_BBY_KONZ NUMBER(38,4) NOT NULL DEFAULT 0 COMMENT 'PV-Kennzahlen in Konzernwährung werden auf Bondatenebene berechnet und im Anschluss daran aggregiert hier eingefügt. PV wenn Abverkauf durch eine_2 Aktion_2 in Kombination mit einem KD Kundenkarten BBY zustande gekommen ist. PV Differenz KDP-BBY-Preis zu Aktionspreis fließt in pv_kdp_bby. PV Differenz Aktionspreis zu Normalpreis fließt in pv_aktion_kdp_bby.',
	PV_BONRABATT_BBY NUMBER(38,4) NOT NULL DEFAULT 0 COMMENT 'Feld beinhaltet die PVs die nur durch die Bonrabatte erzeugt werden. Ein Bonrabatt ist ein Rabatt bei dem ein Kunde ab einem bestimmten Gesamteinkaufswert einen Betrag von der Rechnung abgezogen bekommt (z.B. 10€ Rabatt ab einem Gesamteinkaufswert von 100€). Dieser Wert wird im Bon anteilig von allen Produkten abgezogen. Ein Artikel_2 mit einem Bonrabattwert gilt trotzdem als aktionsfrei wenn er ansonsten in keiner Aktion_2 ist. Bonrabatte stehen in der Tabelle DBP_ODS.ODS_PROMOTION_2 und haben die KONDITIONSART_IDs ZBON oder ZBOV. Für die Bestimmung der Art_2 des BBYs (KDN, KDP, Standard) verwendet man die Flags CUSTOMER_PROMOTION_FG und PROMOTION_ART in DBP_ODS.ODS_PROMOTION. Eine_2 Differenzierung für Bonrabatt BBY ist NICHT notwendig laut Fachbereich, stand 01.12.2022.',
	PV_BONRABATT_BBY_KONZ NUMBER(38,4) NOT NULL DEFAULT 0 COMMENT 'Feld beinhaltet die PVs in Konzernwährung die nur durch die Bonrabatte erzeugt werden. Ein Bonrabatt ist ein Rabatt bei dem ein Kunde ab einem bestimmten Gesamteinkaufswert einen Betrag von der Rechnung abgezogen bekommt (z.B. 10€ Rabatt ab einem Gesamteinkaufswert von 100€). Dieser Wert wird im Bon anteilig von allen Produkten abgezogen. Ein Artikel_2 mit einem Bonrabattwert gilt trotzdem als aktionsfrei wenn er ansonsten in keiner Aktion_2 ist. Bonrabatte stehen in der Tabelle DBP_ODS.ODS_PROMOTION_2 und haben die KONDITIONSART_IDs ZBON oder ZBOV. Für die Bestimmung der Art_2 des BBYs (KDN, KDP, Standard) verwendet man die Flags CUSTOMER_PROMOTION_FG und PROMOTION_ART in DBP_ODS.ODS_PROMOTION. Eine_2 Differenzierung für Bonrabatt BBY ist NICHT notwendig laut Fachbereich, stand 01.12.2022.',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	constraint PK_ARTBEW_MO_SUM primary key (ART_ID, WUP_ID, NB_ID, BEWART_ID, MANDANT_ID, GP_ID, POSTEN_ID, KJMO, EAN_KASSE, BEWART_DET_ID)
)COMMENT='TP2 AIS - Aggregat Artbew_2 auf der Ebene Artikel_2/Monat_2/Markt -Multiset'
;